negativeExample:
import java.util.function.Consumer;

public class NegativeService {
    public void handle(String message) {
        System.out.println("Handling: " + message);
    }

    public void setupHandler() {
        Consumer<String> handler = new Consumer<String>() {
            @Override
            public void accept(String s) {
                // This anonymous class has additional logic and cannot be converted to a simple method reference.
                if (s != null && !s.isEmpty()) {
                    NegativeService.this.handle(s.trim());
                } else {
                    System.err.println("Invalid message");
                }
            }
        };
        handler.accept("World");
    }
}

